//! `crossplat` demonstrates how to keep conditional compilation out of your
//! public API.
//!
//! The crate exposes a single, platform-independent surface. Every
//! `#[cfg(...)]` lives in [`platform`], which selects one implementation of the
//! [`Platform`] trait. Callers never need to write a `cfg` of their own.

mod platform;

pub use platform::{Current, Platform};

/// The name of the platform currently being compiled for.
#[must_use]
pub fn name() -> &'static str {
    Current::NAME
}

/// The memory page size, in bytes, of the current platform.
#[must_use]
pub fn page_size() -> usize {
    Current::page_size()
}

/// A sensible upper bound on the number of useful worker threads.
#[must_use]
pub fn max_threads() -> usize {
    Current::max_threads()
}

//! Platform selection.
//!
//! This module owns *all* of the crate's conditional compilation. Each branch
//! pulls in a small module that implements [`Platform`] for one target family,
//! then re-exports it as [`Current`]. Keeping the dispatch here means the rest
//! of the crate reads as ordinary, portable Rust.

use cfg_if::cfg_if;

cfg_if! {
    if #[cfg(target_arch = "wasm32")] {
        mod wasm;
        pub use wasm::Wasm as Current;
    } else if #[cfg(windows)] {
        mod windows;
        pub use windows::Windows as Current;
    } else if #[cfg(unix)] {
        mod unix;
        pub use unix::Unix as Current;
    } else {
        compile_error!(
            "crossplat does not support this target yet. \
             Add a module under `src/platform/` and a branch to the `cfg_if!` \
             block in `src/platform/mod.rs`."
        );
    }
}

/// The behaviour every supported platform must provide.
///
/// Implement this trait in a per-platform module and add a matching branch to
/// the [`cfg_if!`] dispatch above. No other file needs to change.
pub trait Platform {
    /// A short, human-readable identifier for the platform.
    const NAME: &'static str;

    /// The memory page size, in bytes.
    fn page_size() -> usize;

    /// A reasonable upper bound on useful worker threads.
    fn max_threads() -> usize;
}

use super::Platform;

/// Unix-family platforms: Linux, macOS, the BSDs, and friends.
pub struct Unix;

impl Platform for Unix {
    const NAME: &'static str = "unix";

    fn page_size() -> usize {
        // SAFETY: `sysconf` with `_SC_PAGESIZE` has no preconditions and does
        // not touch memory; it only reads a kernel-provided constant.
        #[allow(unsafe_code)]
        let page_size = unsafe { libc::sysconf(libc::_SC_PAGESIZE) };

        if page_size > 0 { page_size as usize } else { 4096 }
    }

    fn max_threads() -> usize {
        std::thread::available_parallelism().map_or(1, std::num::NonZero::get)
    }
}

use super::Platform;

/// Microsoft Windows.
pub struct Windows;

impl Platform for Windows {
    const NAME: &'static str = "windows";

    fn page_size() -> usize {
        // The default page size on all currently supported Windows versions.
        // Swap in `GetSystemInfo` (from `windows-sys`) here if you need the
        // value reported by the running system.
        4096
    }

    fn max_threads() -> usize {
        std::thread::available_parallelism().map_or(1, std::num::NonZero::get)
    }
}

use super::Platform;

/// The `wasm32` family, typically running inside a host engine.
pub struct Wasm;

impl Platform for Wasm {
    const NAME: &'static str = "wasm32";

    fn page_size() -> usize {
        // WebAssembly linear-memory pages are fixed at 64 KiB by the spec.
        64 * 1024
    }

    fn max_threads() -> usize {
        // Threads require the shared-memory and atomics proposals.
        1
    }
}

use crossplat::{Current, Platform};

fn assert_platform<P: Platform>() {}

#[test]
fn current_implements_platform() {
    assert_platform::<Current>();
}

#[test]
fn metadata_is_sane() {
    assert!(!crossplat::name().is_empty());
    assert!(crossplat::page_size().is_power_of_two());
    assert!(crossplat::max_threads() >= 1);
}

